// LocalName by 1010 (SAD777A). Chrysalism module adaptation.
// Shared functional source: LocalName 0.3.0.0.
// Maintained by 1010: shared core with isolated module storage and lifecycle.

using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Runtime.ExceptionServices;
using System.Runtime.CompilerServices;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Chrysalism.Modules;
using Dalamud.Bindings.ImGui;

namespace ChrysalismExternalModules;

public sealed class LocalName : IChrysalismModule
{
    private IChrysalismModuleContext? context;
    private PayloadContext? payloadContext;
    private IDisposable? implementation;
    private MethodInfo? openSettings;
    private MethodInfo? command;
    private bool disposed;

    public ChrysalismModuleInfo Info { get; } = new(
        nameof(LocalName), "本地改名 LocalName", "本地姓名、区服、称号、部队显示及头顶特效。",
        "0.3.0.0", "1010", "界面",
        "https://github.com/SAD777A/1010/tree/main/LocalName");

    public bool HasSettings => true;

    public void Initialize(IChrysalismModuleContext moduleContext)
    {
        ObjectDisposedException.ThrowIf(disposed, this);
        context = moduleContext;
    }

    public void Enable()
    {
        ObjectDisposedException.ThrowIf(disposed, this);
        if (implementation != null) return;
        var host = context ?? throw new InvalidOperationException("LocalName 模块尚未初始化。");
        EnsureNoConflict(host);
        var directory = Path.Combine(host.DataDirectory, "LocalName");
        Directory.CreateDirectory(directory);
        var child = new PayloadContext(AssemblyLoadContext.GetLoadContext(host.PluginInterface.GetType().Assembly)
            ?? AssemblyLoadContext.GetLoadContext(typeof(Dalamud.Plugin.IDalamudPluginInterface).Assembly)
            ?? AssemblyLoadContext.Default);
        IDisposable? instance = null;
        try
        {
            using var compressed = new MemoryStream(ReadPayload());
            using var input = new GZipStream(compressed, CompressionMode.Decompress);
            using var bytes = new MemoryStream();
            input.CopyTo(bytes);
            bytes.Position = 0;
            var assembly = child.LoadFromStream(bytes);
            var type = assembly.GetType("LocalName.Unified.Plugin", true)!;
            var settingsMethod = type.GetMethod("OpenModuleSettings")
                ?? throw new MissingMethodException("LocalName 设置入口缺失。");
            var commandMethod = type.GetMethod("HandleModuleCommand")
                ?? throw new MissingMethodException("LocalName 命令入口缺失。");
            instance = (IDisposable)Activator.CreateInstance(type,
                host.PluginInterface, host.Log, host.GetState("LocalName.Configuration"),
                (Action<string>)(json => host.SetState("LocalName.Configuration", json)), directory)!;
            payloadContext = child;
            implementation = instance;
            openSettings = settingsMethod;
            command = commandMethod;
        }
        catch (Exception exception)
        {
            try { instance?.Dispose(); }
            finally { child.Unload(); }
            if (exception is TargetInvocationException { InnerException: { } inner })
                ExceptionDispatchInfo.Capture(inner).Throw();
            throw;
        }
    }

    public void Disable()
    {
        var instance = Interlocked.Exchange(ref implementation, null);
        var child = Interlocked.Exchange(ref payloadContext, null);
        openSettings = command = null;
        try { instance?.Dispose(); }
        finally { child?.Unload(); }
    }

    public void Update(TimeSpan elapsed)
    {
        // Upstream owns its Framework subscription; never advance it twice.
    }

    public bool DrawSettings()
    {
        ImGui.BeginDisabled(implementation == null);
        try
        {
            var start = ImGui.GetCursorScreenPos().X;
            var width = ImGui.GetContentRegionAvail().X;
            if (ImGui.Button("打开 LocalName 设置")) Invoke(openSettings, null);
            if (width - (ImGui.GetItemRectMax().X - start) >= ImGui.CalcTextSize("测试聊天替换").X + ImGui.GetStyle().FramePadding.X * 2 + ImGui.GetStyle().ItemSpacing.X)
                ImGui.SameLine();
            if (ImGui.Button("测试聊天替换")) Invoke(command, new object[] { "test" });
        }
        finally { ImGui.EndDisabled(); }
        ImGui.Spacing();
        if (implementation == null) ImGui.TextDisabled("启用模块后可打开设置。");
        return false;
    }

    public bool TryHandleCommand(string arguments)
    {
        if (implementation == null) return false;
        Invoke(command, new object[] { arguments });
        return true;
    }

    public void Dispose()
    {
        if (disposed) return;
        disposed = true;
        try { Disable(); }
        finally { context = null; }
    }

    private void Invoke(MethodInfo? method, object[]? arguments)
    {
        if (implementation == null || method == null) return;
        try { method.Invoke(implementation, arguments); }
        catch (TargetInvocationException exception) when (exception.InnerException != null)
        { ExceptionDispatchInfo.Capture(exception.InnerException).Throw(); }
    }

    private static void EnsureNoConflict(IChrysalismModuleContext host)
    {
        if (host.PluginInterface.InstalledPlugins.Any(plugin => plugin.IsLoaded &&
                string.Equals(plugin.InternalName, "LocalName", StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException("请先停用独立 LocalName 插件，再启用此模块。");
        var configuration = host.PluginInterface.GetPluginConfig();
        var names = configuration?.GetType().GetProperty("CustomNames")?.GetValue(configuration);
        if (names != null && names.GetType().GetProperties().Select(property => property.GetValue(names))
                .Any(profile => profile?.GetType().GetProperty("Enabled")?.GetValue(profile) is true))
            throw new InvalidOperationException("请先关闭 Chrysalism 的自定义名称，再启用 LocalName 模块。");
    }

    private sealed class PayloadContext : AssemblyLoadContext
    {
        private readonly AssemblyLoadContext host;
        public PayloadContext(AssemblyLoadContext host) : base("Chrysalism.LocalName", true) => this.host = host;
        protected override Assembly? Load(AssemblyName name) => host.LoadFromAssemblyName(name);
    }

    // Keep binary data in the file's trailing comment, outside the CLR string heap.
    private static string SourceFile([CallerFilePath] string path = "") => path;
    private const int PayloadLength = 12096268;
    private const string PayloadSha256 = "AAB5CEACEC6C967468D43006781AC07444DD68D3CE5A193168B0DDF7E8CD8BEF";
    private static readonly byte[] PayloadMarker = Encoding.ASCII.GetBytes("\n/* CHRYSALISM_LOCALNAME_PAYLOAD_V1\n");
    private static readonly byte[] PayloadEnd = Encoding.ASCII.GetBytes("\n*/\n");

    private static byte[] ReadPayload()
    {
        using var file = File.OpenRead(SourceFile());
        var size = PayloadMarker.Length + PayloadLength + PayloadEnd.Length;
        if (file.Length < size) throw new InvalidDataException("LocalName 模块资源不完整，请重新导入原始文件。");
        file.Seek(-size, SeekOrigin.End);
        var marker = new byte[PayloadMarker.Length];
        file.ReadExactly(marker);
        if (!marker.AsSpan().SequenceEqual(PayloadMarker)) throw new InvalidDataException("LocalName 模块资源头不匹配。");
        var text = new byte[PayloadLength];
        file.ReadExactly(text);
        var end = new byte[PayloadEnd.Length];
        file.ReadExactly(end);
        if (!end.AsSpan().SequenceEqual(PayloadEnd)) throw new InvalidDataException("LocalName 模块资源尾不匹配。");
        var binary = Convert.FromBase64String(Encoding.ASCII.GetString(text));
        if (!string.Equals(Convert.ToHexString(SHA256.HashData(binary)), PayloadSha256, StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException("LocalName 模块资源校验失败。");
        return binary;
    }
}

/* CHRYSALISM_LOCALNAME_PAYLOAD_V1

*/
